const Icon = (props: SVGProps<SVGSVGElement>) => <svg xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid" viewBox="0 0 256 373" {...props}><path fill="#00d1b2" d="M0 256 23.273 93.09 116.363 0l116.364 116.364-69.818 69.818L256 279.272l-139.636 93.092z" /></svg>;

